179|                semanticLabel = "归档目录"
180|            } else if windowRect.maxX >= contentBounds.width - 20, windowRect.width <= 420 {
181|                semanticLabel = "归档信息"
182|            } else if windowRect.width >= 400 {
183|                semanticLabel = "归档内容"
184|            } else {
185|                semanticLabel = nil
186|            }
187|            if let semanticLabel {
188|                view.setAccessibilityLabel(semanticLabel)
189|                view.setAccessibilityIdentifier("\(semanticLabel)容器")
190|            }
191|        }
192|        if let splitView = view as? NSSplitView {
193|            splitView.setAccessibilityLabel("归档分栏")
194|            for (index, pane) in splitView.arrangedSubviews.enumerated() {
195|                let paneLabel: String
