7|    let metadataByEntryID: [ArchiveEntryID: ArchiveEntryMetadata]
8|    @Binding var selection: ArchiveEntryID?
9|
10|    func makeCoordinator() -> Coordinator { Coordinator(parent: self) }
11|
12|    func makeNSView(context: Context) -> NSScrollView {
13|        let table = NSTableView()
14|        table.identifier = NSUserInterfaceItemIdentifier("归档文件列表")
15|        table.setAccessibilityIdentifier("归档文件列表")
16|        table.usesAlternatingRowBackgroundColors = true
17|        table.allowsMultipleSelection = false
18|        table.delegate = context.coordinator
19|        table.dataSource = context.coordinator
20|
21|        for (identifier, title, width) in [("name", "名称", 300.0), ("type", "类型", 100.0), ("size", "大小", 120.0), ("date", "修改日期", 180.0)] {
22|            let column = NSTableColumn(identifier: NSUserInterfaceItemIdentifier(identifier))
23|            column.title = title
24|            column.width = width
25|            table.addTableColumn(column)
26|        }
27|
28|        let scrollView = NSScrollView()
29|        scrollView.documentView = table
30|        scrollView.hasVerticalScroller = true
31|        scrollView.autohidesScrollers = true
32|        return scrollView
33|    }
34|
35|    func updateNSView(_ scrollView: NSScrollView, context: Context) {
36|        context.coordinator.parent = self
37|        guard let table = scrollView.documentView as? NSTableView else { return }
38|        table.reloadData()
39|        if let selected = selection, let row = entries.firstIndex(where: { $0.id == selected }) {
40|            table.selectRowIndexes(IndexSet(integer: row), byExtendingSelection: false)
41|        }
42|    }
43|
44|    final class Coordinator: NSObject, NSTableViewDataSource, NSTableViewDelegate {
45|        var parent: ArchiveListView
46|        init(parent: ArchiveListView) { self.parent = parent }
47|
48|        func numberOfRows(in tableView: NSTableView) -> Int { parent.entries.count }
49|
50|        func tableView(_ tableView: NSTableView, viewFor tableColumn: NSTableColumn?, row: Int) -> NSView? {
51|            let entry = parent.entries[row]
52|            let metadata = parent.metadataByEntryID[entry.id]
53|            let value: String
54|            switch tableColumn?.identifier.rawValue {
55|            case "name": value = entry.displayPath
56|            case "type": value = metadata?.type ?? "文件"
57|            case "size": value = metadata?.size ?? "—"
58|            default: value = metadata?.modifiedDate ?? "—"
59|            }
60|            let field = NSTextField(labelWithString: value)
61|            field.usesSingleLineMode = true
62|            field.maximumNumberOfLines = 1
63|            field.lineBreakMode = .byTruncatingMiddle
64|            field.toolTip = value
65|            field.setAccessibilityLabel(value)
66|            return field
67|        }
68|
69|        func tableViewSelectionDidChange(_ notification: Notification) {
70|            guard let table = notification.object as? NSTableView,
71|                  parent.entries.indices.contains(table.selectedRow) else { return }
72|            parent.selection = parent.entries[table.selectedRow].id
73|        }
74|    }
