6|public enum WindowsZIPProfileError: Error, Equatable, Sendable {
7|    case noInputs
8|    case invalidName(String)
9|    case collision(String, String)
10|    case unsupportedItem(String)
11|    case outputExists
12|    case io(Int32)
13|}
14|
15|extension ZIPArchiveProvider {
16|    public func createWindowsZIP(at outputURL: URL, inputs: [URL]) throws {
17|        guard !FileManager.default.fileExists(atPath: outputURL.path) else {
18|            throw WindowsZIPProfileError.outputExists
19|        }
20|        let files = try WindowsZIPPreflight().collect(inputs: inputs)
21|        let stageURL = outputURL.deletingLastPathComponent().appending(
22|            path: "." + outputURL.lastPathComponent + ".staging-" + UUID().uuidString
23|        )
24|        var stageExists = false
25|        defer {
26|            if stageExists { try? FileManager.default.removeItem(at: stageURL) }
27|        }
28|
29|        let writer = try ZIPBridgeWriter(url: stageURL)
30|        stageExists = true
31|        for file in files {
32|            try writer.add(sourceURL: file.sourceURL, archivePath: file.archivePath)
33|        }
34|        for file in files {
35|            guard try file.fingerprint == SourceFingerprint(url: file.sourceURL) else {
36|                throw ArchiveError.sourceChanged
37|            }
38|        }
39|        try writer.finish()
40|        try syncFile(at: stageURL)
41|        try publishExclusively(stageURL: stageURL, outputURL: outputURL)
42|        stageExists = false
43|    }
44|
45|    private func syncFile(at url: URL) throws {
46|        let descriptor = url.withUnsafeFileSystemRepresentation { path -> Int32 in
47|            guard let path else { return -1 }
48|            return Darwin.open(path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW)
49|        }
50|        guard descriptor >= 0 else { throw WindowsZIPProfileError.io(errno) }
51|        defer { Darwin.close(descriptor) }
52|        guard fsync(descriptor) == 0 else { throw WindowsZIPProfileError.io(errno) }
53|    }
54|
55|    private func publishExclusively(stageURL: URL, outputURL: URL) throws {
56|        let linkResult = stageURL.withUnsafeFileSystemRepresentation { stagePath in
57|            outputURL.withUnsafeFileSystemRepresentation { outputPath in
58|                guard let stagePath, let outputPath else { return Int32(-1) }
59|                return Darwin.link(stagePath, outputPath)
60|            }
61|        }
62|        guard linkResult == 0 else {
63|            if errno == EEXIST { throw WindowsZIPProfileError.outputExists }
64|            throw WindowsZIPProfileError.io(errno)
65|        }
66|        do {
67|            try FileManager.default.removeItem(at: stageURL)
68|            try syncDirectory(at: outputURL.deletingLastPathComponent())
69|        } catch {
70|            try? FileManager.default.removeItem(at: outputURL)
71|            throw error
72|        }
73|    }
74|
75|    private func syncDirectory(at url: URL) throws {
76|        let descriptor = url.withUnsafeFileSystemRepresentation { path -> Int32 in
77|            guard let path else { return -1 }
78|            return Darwin.open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW)
79|        }
80|        guard descriptor >= 0 else { throw WindowsZIPProfileError.io(errno) }
81|        defer { Darwin.close(descriptor) }
82|        guard fsync(descriptor) == 0 else { throw WindowsZIPProfileError.io(errno) }
83|    }
