86|private struct WindowsZIPInputFile {
87|    let sourceURL: URL
88|    let archivePath: String
89|    let fingerprint: SourceFingerprint
90|}
91|
92|private struct SourceFingerprint: Equatable {
93|    let resourceIdentifier: String
94|    let fileSize: Int
95|    let modificationTime: TimeInterval
96|
97|    init(url: URL) throws {
98|        let values = try url.resourceValues(forKeys: [
99|            .fileResourceIdentifierKey,
100|            .fileSizeKey,
101|            .contentModificationDateKey,
102|            .isRegularFileKey,
103|            .isSymbolicLinkKey,
104|        ])
105|        guard values.isRegularFile == true, values.isSymbolicLink != true else {
106|            throw WindowsZIPProfileError.unsupportedItem(url.lastPathComponent)
107|        }
108|        resourceIdentifier = String(describing: values.fileResourceIdentifier)
109|        fileSize = values.fileSize ?? -1
110|        modificationTime = values.contentModificationDate?.timeIntervalSinceReferenceDate ?? -1
111|    }
112|}
113|
114|private struct WindowsZIPPreflight {
115|    private let resourceKeys: Set<URLResourceKey> = [
116|        .isRegularFileKey,
117|        .isDirectoryKey,
118|        .isSymbolicLinkKey,
119|        .fileResourceIdentifierKey,
120|        .fileSizeKey,
121|        .contentModificationDateKey,
122|    ]
123|
124|    func collect(inputs: [URL]) throws -> [WindowsZIPInputFile] {
125|        guard !inputs.isEmpty else { throw WindowsZIPProfileError.noInputs }
126|        var candidates: [(URL, String)] = []
127|        for input in inputs {
128|            let values = try input.resourceValues(forKeys: resourceKeys)
129|            if values.isSymbolicLink == true {
130|                throw WindowsZIPProfileError.unsupportedItem(input.lastPathComponent)
131|            }
132|            if values.isRegularFile == true {
133|                candidates.append((input, input.lastPathComponent))
134|            } else if values.isDirectory == true {
135|                candidates.append(contentsOf: try files(under: input))
136|            } else {
137|                throw WindowsZIPProfileError.unsupportedItem(input.lastPathComponent)
138|            }
139|        }
140|
141|        let normalized = try candidates.compactMap { sourceURL, relativePath -> WindowsZIPInputFile? in
142|            let components = relativePath.split(separator: "/").map(String.init)
143|            if shouldSuppress(components: components) { return nil }
144|            let archivePath = components
145|                .map { $0.precomposedStringWithCanonicalMapping }
146|                .joined(separator: "/")
147|            try validate(path: archivePath)
148|            return WindowsZIPInputFile(
149|                sourceURL: sourceURL,
150|                archivePath: archivePath,
151|                fingerprint: try SourceFingerprint(url: sourceURL)
152|            )
153|        }
154|        guard !normalized.isEmpty else { throw WindowsZIPProfileError.noInputs }
155|
156|        var seen: [String: String] = [:]
157|        for file in normalized {
158|            let key = file.archivePath.precomposedStringWithCanonicalMapping
159|                .lowercased(with: Locale(identifier: "en_US_POSIX"))
160|            if let existing = seen[key] {
161|                let ordered = [existing, file.archivePath].sorted(by: >)
162|                throw WindowsZIPProfileError.collision(ordered[0], ordered[1])
163|            }
164|            seen[key] = file.archivePath
165|        }
166|        return normalized.sorted {
167|            Array($0.archivePath.utf8).lexicographicallyPrecedes(Array($1.archivePath.utf8))
168|        }
169|    }
170|
171|    private func files(under root: URL) throws -> [(URL, String)] {
172|        var enumerationError: Error?
173|        guard let enumerator = FileManager.default.enumerator(
174|            at: root,
175|            includingPropertiesForKeys: Array(resourceKeys),
176|            options: [.skipsPackageDescendants],
177|            errorHandler: { _, error in
178|                enumerationError = error
179|                return false
180|            }
181|        ) else {
182|            throw WindowsZIPProfileError.unsupportedItem(root.lastPathComponent)
183|        }
184|        var result: [(URL, String)] = []
185|        let prefix = root.standardizedFileURL.path + "/"
186|        while let url = enumerator.nextObject() as? URL {
187|            let values = try url.resourceValues(forKeys: resourceKeys)
188|            guard url.standardizedFileURL.path.hasPrefix(prefix) else {
189|                throw WindowsZIPProfileError.unsupportedItem(url.lastPathComponent)
190|            }
191|            let relativePath = String(url.standardizedFileURL.path.dropFirst(prefix.count))
192|            if values.isSymbolicLink == true {
193|                throw WindowsZIPProfileError.unsupportedItem(relativePath)
194|            }
195|            if values.isRegularFile == true {
196|                result.append((url, relativePath))
197|            } else if values.isDirectory != true {
198|                throw WindowsZIPProfileError.unsupportedItem(relativePath)
199|            }
200|        }
201|        if let enumerationError { throw enumerationError }
202|        return result
203|    }
204|
205|    private func shouldSuppress(components: [String]) -> Bool {
206|        components.contains { component in
207|            component == ".DS_Store" || component == "__MACOSX" || component.hasPrefix("._")
208|        }
209|    }
210|
211|    private func validate(path: String) throws {
212|        let components = path.split(separator: "/", omittingEmptySubsequences: false).map(String.init)
213|        guard !components.isEmpty, path.utf16.count <= 180 else {
214|            throw WindowsZIPProfileError.invalidName(path)
215|        }
216|        let forbidden = CharacterSet(charactersIn: "<>:\"/\\|?*")
217|        let reserved = Set(["CON", "PRN", "AUX", "NUL"])
218|        for component in components {
219|            let upperStem = component.split(separator: ".", maxSplits: 1).first
220|                .map(String.init)?.uppercased() ?? ""
221|            let isNumberedDevice = (upperStem.hasPrefix("COM") || upperStem.hasPrefix("LPT"))
222|                && upperStem.count == 4
223|                && upperStem.last.map { ("1"..."9").contains(String($0)) } == true
224|            let invalid = component.isEmpty
225|                || component.utf16.count > 255
226|                || component.hasSuffix(".")
227|                || component.hasSuffix(" ")
228|                || component.unicodeScalars.contains { scalar in
229|                    scalar.value < 0x20 || forbidden.contains(scalar)
230|                }
231|                || reserved.contains(upperStem)
232|                || isNumberedDevice
233|            if invalid { throw WindowsZIPProfileError.invalidName(component) }
234|        }
235|    }
236|}
